# Generated by build.py from recipe.yml for recipe imap-start-a-mailbox-with-folders. Do not edit.
Set-Location $PSScriptRoot
[IO.File]::WriteAllText((Join-Path $PWD 'sent.eml'), "From: ann@example.com`r`nTo: bob@example.com`r`nSubject: Minutes`r`n`r`nThe minutes are attached.`r`n")
$server0 = Start-Process surl -ArgumentList '--mail-domain', 'example.com', '--mailbox', '"ann@example.com:annpass;folders=Sent,Drafts,Archive"', '--mailbox', '"bob@example.com:bobpass;folders=Sent,Drafts,Archive"', '--mailbox', 'carol@example.com:carolpass', '--mailbox', '"dave@example.com:davepass;folders=Sent', 'Items,Archive/2026"', '--mailbox', '"erin@example.com:erinpass;folders=Paid%2CUnpaid"', 'imap://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -u ann@example.com:annpass imap://127.0.0.1:8080/ } finally { Stop-Process $server0 }
